#include <stdio.h>
int main(void){int n,at[100],bt[100],p[100],rem[100],done[100]={0},wt[100],tat[100],i,t=0,k;float aw=0,avg=0;printf("Number of processes: ");scanf("%d",&n);if(n<1||n>100)return 1;for(i=0;i<n;i++){printf("Arrival and burst P%d: ",i+1);scanf("%d%d",&at[i],&bt[i]);p[i]=i+1;}for(k=0;k<n;k++){int idx=-1;for(i=0;i<n;i++)if(!done[i]&&at[i]<=t&&(idx==-1||bt[i]<bt[idx]))idx=i;if(idx==-1){t++;k--;continue;}wt[idx]=t-at[idx];t+=bt[idx];tat[idx]=t-at[idx];done[idx]=1;}printf("PID\tAT\tBT\tWT\tTAT\n");for(i=0;i<n;i++){aw+=wt[i];avg+=tat[i];printf("P%d\t%d\t%d\t%d\t%d\n",p[i],at[i],bt[i],wt[i],tat[i]);}printf("Avg WT=%.2f Avg TAT=%.2f\n",aw/n,avg/n);}